// Reactor: errors, timeouts and empties become values at each source, then Mono.zip
Mono<Quote> best(String destination) {
    return Mono.zip(inTime(northline.quote(destination)), inTime(eastgate.quote(destination)), inTime(fjord.quote(destination)))
            .map(t -> Stream.of(t.getT1(), t.getT2(), t.getT3())
                    .flatMap(Optional::stream)
                    .min(Comparator.comparing(Quote::price)))
            .flatMap(best -> best.map(Mono::just).orElseGet(() -> fromCache(destination)))
            .doOnNext(q -> { if (!q.stale()) cache.remember(q); });
}

Mono<Optional<Quote>> inTime(Mono<Quote> call) {
    return call.timeout(DEADLINE)
            .map(Optional::of)
            .onErrorResume(e -> Mono.just(Optional.empty()))   // a failure or a timeout: no answer
            .defaultIfEmpty(Optional.empty());                 // an empty source would empty the zip
}

Mono<Quote> fromCache(String destination) {
    Quote last = cache.lastGood(destination);
    return last != null ? Mono.just(last.asStale()) : Mono.error(new NoQuoteException(destination));
}

kotlin.src:
class BestQuote(
    private val providers: List<Provider>,
    private val deadline: Duration,
    private val cache: QuoteCache = QuoteCache(),
) {
    suspend fun quote(destination: String): Quote {
        val answers = supervisorScope {                                    // 1. a failed call doesn't cancel the others
            providers
                .map { p -> async { withTimeoutOrNull(deadline) { p.quote(destination) } } }   // 2. late is null, not an exception
                .map { it.awaitOrNull() }                                  // 3. failed is null too
        }.filterNotNull()
        val best = answers.minByOrNull { it.price }
        if (best != null) {
            cache.remember(best)
            return best
        }
        return cache.lastGood(destination)?.asStale() ?: throw NoQuoteException(destination)   // 4. stale beats nothing
    }

    private suspend fun Deferred<Quote?>.awaitOrNull(): Quote? =
        try {
            await()
        } catch (e: CancellationException) {
            currentCoroutineContext().ensureActive()   // we were cancelled ourselves: this rethrows
            null                                        // only the provider's call ended that way: no answer
        } catch (e: Exception) {
            null                                        // the provider failed: no answer from it
        }
}

